package com.brasa.restaurant.model;import jakarta.persistence.*;@Entity@Table(name="categorias")public class Categoria extends BaseEntity{@Column(name="restaurante_id",nullable=false)private String restauranteId;@Column(nullable=false)private String nome;@Column(name="ordem_exibicao")private int ordem;public String getRestauranteId(){return restauranteId;}public void setRestauranteId(String v){restauranteId=v;}public String getNome(){return nome;}public void setNome(String v){nome=v;}public int getOrdem(){return ordem;}public void setOrdem(int v){ordem=v;}}
